{
    options.AddPolicy("CORSPolicy", builder =>
    {
        builder.WithOrigins("https://example.com")
               .AllowAnyMethod()
               .AllowCredentials();
    });
    options.DefaultPolicy = options.BuildPolicy("CORSPolicy");
}));
